mapper.insert:
INSERT INTO fgc.reconciliation_result ( reconciliation_run_id, match_group_key, contract_id, expected_agent_id, actual_agent_id, actual_source_agent_code, commission_item_id, installment_no, result_type, expected_total_amount, actual_total_amount, difference_amount, primary_reason_code, secondary_reason_codes, detail_snapshot ) VALUES ( #{reconciliationRunId}, #{matchGroupKey}, #{contractId}, #{expectedAgentId}, #{actualAgentId}, #{actualSourceAgentCode}, #{commissionItemId}, #{installmentNo}, #{resultType}, #{expectedTotalAmount}, #{actualTotalAmount}, #{differenceAmount}, #{primaryReasonCode},
ARRAY[
#{reason}
]::text[]
ARRAY[]::text[] , CAST(#{detailSnapshotJson} AS jsonb) ) ON CONFLICT ON CONSTRAINT uq_reconciliation_result DO NOTHING

mapper.select:
SELECT reconciliation_result_id
  FROM fgc.reconciliation_result
 WHERE reconciliation_run_id = #{reconciliationRunId}
   AND match_group_key = #{matchGroupKey}

SELECT COUNT(*)
  FROM fgc.reconciliation_result
 WHERE reconciliation_run_id = #{reconciliationRunId}

SELECT EXISTS ( SELECT 1 FROM fgc.insurance_contract contract WHERE contract.contract_id = #{contractId} AND contract.current_status IN ('CANCELLED', 'TERMINATED', 'MATURED', 'LAPSED') ) AS invalidContractPayment, CASE WHEN CAST(#{expectedAgentId} AS bigint) IS NULL OR CAST(#{actualAgentId} AS bigint) IS NULL THEN FALSE ELSE COALESCE(( SELECT expected.organization_id <> actual.organization_id FROM fgc.agent expected, fgc.agent actual WHERE expected.agent_id = #{expectedAgentId} AND actual.agent_id = #{actualAgentId} ), FALSE) END AS organizationMismatch,
(SELECT COUNT(DISTINCT header.policy_version_id) > 1 FROM fgc.journal_header header WHERE header.journal_header_id IN
#{id}
AND header.policy_version_id IS NOT NULL)
FALSE AS policyVersionError,
EXISTS ( SELECT 1 FROM fgc.vw_journal_imbalance imbalance WHERE imbalance.journal_header_id IN
#{id}
)
FALSE AS journalImbalance

SELECT result.reconciliation_result_id AS reconciliationResultId, contract.contract_no AS contractNo, item.item_code AS commissionItemCode, item.item_name AS commissionItemName, result.installment_no AS installmentNo, expected_agent.agent_id AS expectedAgentId, expected_agent.agent_code AS expectedAgentCode, expected_agent.agent_name AS expectedAgentName, expected_org.organization_name AS expectedOrganizationName, actual_agent.agent_id AS actualAgentId, actual_agent.agent_code AS actualAgentCode, actual_agent.agent_name AS actualAgentName, actual_org.organization_name AS actualOrganizationName, result.actual_source_agent_code AS actualSourceAgentCode, result.expected_total_amount AS expectedTotalAmount, result.actual_total_amount AS actualTotalAmount, result.difference_amount AS differenceAmount, result.result_type AS resultType, result.primary_reason_code AS primaryReasonCode, array_to_string(result.secondary_reason_codes, ',') AS secondaryReasonCodesCsv, result.created_at AS createdAt
WHERE result.reconciliation_run_id = #{reconciliationRunId}
AND result.result_type = #{resultType}
ORDER BY result.created_at
ASC DESC , result.reconciliation_result_id
ASC DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM fgc.reconciliation_result result
 WHERE result.reconciliation_run_id = #{reconciliationRunId}

   AND result.result_type = #{resultType}
